// Exercise the actual LED settings functions with four independently configured RGBW buses.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const path = require('node:path');

function settings(types, shared = true) {
  const source = fs.readFileSync(path.join(__dirname, '../wled00/data/settings_leds.htm'), 'utf8');
  const script = source.match(/<script>([\s\S]*?)<\/script>/)[1];
  const form = {};
  const selects = types.map((type, i) => {
    form[`LT${i}`] = { name: `LT${i}`, value: String(type), querySelectorAll: () => [] };
    form[`LD${i}`] = { value: '0' };
    form[`LC${i}`] = { value: String([119, 118, 31, 31][i] || 1) };
    form[`SL${i}`] = { value: '0' };
    return form[`LT${i}`];
  });
  form.querySelectorAll = () => selects;
  const document = {
    Sf: form,
    ledTypes: [{ i: 30, c: 3, t: 'D' }, { i: 22, c: 1, t: 'D' }],
    createElement: () => ({}),
    head: { appendChild() {} }
  };
  const context = vm.createContext({ document, d: document, gId: () => null });
  vm.runInContext(script, context);
  context.bLimits(1, 2048, 32000, 8192, 5, shared ? 4 : 2, 2, 0, 6, 4, shared ? 1 : 0);
  return context;
}

test('four RGBW buses share one physical worker and pass native settings validation', () => {
  const page = settings([30, 30, 30, 30]);
  const usage = page.getDuse();
  assert.equal(usage.rmtUsed, 1);
  assert.equal(usage.sharedUsed, 4);
  for (let i = 0; i < 4; i++) assert.equal(page.isBCok(i, usage), true);
  page.updateTypeDropdowns();
  for (let i = 0; i < 4; i++) assert.equal(page.d.Sf[`LD${i}`].value, '0');
});

test('stock C3 keeps its two-output limit', () => {
  const page = settings([30, 30, 30], false);
  const usage = page.getDuse();
  assert.equal(usage.rmtUsed, 3);
  assert.equal(page.isBCok(2, usage), false);
});

test('shared target rejects a fifth bus and unsupported one-wire protocols', () => {
  const fifth = settings([30, 30, 30, 30, 30]);
  assert.equal(fifth.isBCok(4, fifth.getDuse()), false);
  const mixed = settings([30, 22]);
  assert.equal(mixed.isBCok(1, mixed.getDuse()), false);
});
